package Lec14;

public class First_string {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		String str= "ABC";
		System.out.println(str);
		
		str = str.concat("DEF"); // add kar raha hai
		System.out.println(str);
		System.out.println(str.length());// length batayega
		System.out.println(str.charAt(0)); // index ka no. print karega 
	}

}
